<?php
 spl_autoload_register(function($className) { if (safe_strpos($className, "ehr\\") === 0) { $name = substr($className, 4); if (safe_strpos($name, 'i') === 0) { $name = substr($name, 1); } if (in_array($name, [ 'Link', 'LinkSetup', 'LinkWrapper', 'Resource', 'ResourceItem', 'ResourceItemMan', 'LinkJSON', 'LinkGUID', 'LinkParams' ])) { $file = lcfirst($name); $fileName = "base/{$file}.php"; } if (in_array($name, ['Exchange', 'ParamsHTTP'])) { $file = lcfirst($name); $fileName = "exchange/{$file}.php"; } if (in_array($name, ['Logger', 'Mail'])) { $file = lcfirst($name); $fileName = "{$file}.php"; } if (safe_strpos($name, 'Practitioner') === 0) { $file = lcfirst(str_replace('Practitioner', '', $name)); $fileName = "resource/practitioner/{$file}.php"; } if (safe_strpos($name, 'Recipe') === 0) { $file = lcfirst(str_replace('Recipe', '', $name)); $fileName = "resource/recipe/{$file}.php"; } if (safe_strpos($name, 'Patient') === 0) { $file = lcfirst(str_replace('Patient', '', $name)); $fileName = "resource/patient/{$file}.php"; } if (isset($fileName)) { require_once __DIR__ . '/' . $fileName; } } }); 